'use strict'

const https = require('node:https')
const fs = require('node:fs')
const path = require('node:path')
const { Pool } = require('/tmp/cxbench-undici/01e89e95e9-file')

const dir = '/tmp/cxbench-undici/01e89e95e9-file/test/fixtures'
const key = fs.readFileSync(path.join(dir, 'key.pem'))
const cert = fs.readFileSync(path.join(dir, 'cert.pem'))

const server = https.createServer({ key, cert }, (req, res) => {
  res.writeHead(200)
  res.end('ok')
})

server.listen(0, async () => {
  const port = server.address().port
  const pool = new Pool(`https://localhost:${port}`, {
    pipelining: 10,
    connections: 2,
    connect: { ca: cert, servername: 'definitely-not-localhost.example.com' }
  })

  const results = await Promise.allSettled(
    Array.from({ length: 20 }, () => pool.request({ path: '/', method: 'GET' }))
  )

  const codes = {}
  for (const r of results) {
    const code = r.status === 'fulfilled' ? 'OK' : (r.reason?.code ?? r.reason?.message)
    codes[code] = (codes[code] ?? 0) + 1
  }
  console.log('results:', codes)
  await pool.close()
  server.close()
})
